//go:build linux

package main

import (
	"context"
	"crypto/tls"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"net/netip"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"
	"time"

	"github.com/aonsyed/cyberpanel/platform/internal/apiserver"
)

type configuration struct{Listen string `json:"listen"`;TLSCertificate string `json:"tls_certificate"`;TLSPrivateKey string `json:"tls_private_key"`;CoreSocket string `json:"core_socket"`;GatewaySigner string `json:"gateway_signer"`;UIDistRoot string `json:"ui_dist_root"`;UIMaximumBytes int64 `json:"ui_maximum_bytes"`;AllowedHosts []string `json:"allowed_hosts"`;AllowedOrigins []string `json:"allowed_origins"`;TrustedProxies []string `json:"trusted_proxies"`;ForwardedMode apiserver.ForwardedMode `json:"forwarded_mode"`;AllowPlaintextLoopback bool `json:"allow_plaintext_loopback"`;SessionCookieName string `json:"session_cookie_name"`;PreviewDomain string `json:"preview_domain"`;PreviewUpstream string `json:"preview_upstream"`;PreviewMaximumRequestBytes int64 `json:"preview_maximum_request_bytes"`;PreviewMaximumResponseBytes int64 `json:"preview_maximum_response_bytes"`;RequestTimeout time.Duration `json:"request_timeout"`;RatePerSecond float64 `json:"rate_per_second"`;RateBurst float64 `json:"rate_burst"`}

func main(){flags:=flag.NewFlagSet("paneld",flag.ExitOnError);configPath:=flags.String("config","/etc/cyberpanel/panel-gateway.json","gateway configuration");_ = flags.Parse(os.Args[1:]);if flags.NArg()!=0{log.Fatal("paneld accepts no positional arguments")};config,err:=loadConfiguration(*configPath);if err!=nil{log.Fatalf("load configuration: %v",err)};if err=run(config);err!=nil{log.Fatal(err)}}

func run(config configuration)error{registry,err:=apiserver.NewDomainRegistry();if err!=nil{return fmt.Errorf("initialize API catalog: %w",err)};transport,err:=apiserver.NewUnixCoreTransport(config.CoreSocket);if err!=nil{return fmt.Errorf("initialize core transport: %w",err)};signer,err:=apiserver.LoadSigner(config.GatewaySigner);if err!=nil{return fmt.Errorf("load gateway trust key: %w",err)};ui,err:=apiserver.LoadStaticUI(config.UIDistRoot,config.UIMaximumBytes);if err!=nil{return fmt.Errorf("load immutable UI: %w",err)};proxies:=make([]netip.Prefix,0,len(config.TrustedProxies));for _,raw:=range config.TrustedProxies{prefix,parseErr:=netip.ParsePrefix(raw);if parseErr!=nil||prefix!=prefix.Masked(){return fmt.Errorf("invalid trusted proxy prefix %q",raw)};proxies=append(proxies,prefix)};gateway,err:=apiserver.NewGateway(registry,transport,signer,apiserver.GatewayPolicy{AllowedHosts:config.AllowedHosts,AllowedOrigins:config.AllowedOrigins,TrustedProxies:proxies,ForwardedMode:config.ForwardedMode,AllowPlaintextLoopback:config.AllowPlaintextLoopback,SessionCookieName:config.SessionCookieName,RequestTimeout:config.RequestTimeout,RatePerSecond:config.RatePerSecond,RateBurst:config.RateBurst});if err!=nil{return fmt.Errorf("initialize gateway: %w",err)};gateway.WithUI(ui);previewProxy,err:=apiserver.NewPreviewProxy(transport,config.PreviewDomain,config.PreviewUpstream,config.SessionCookieName,config.PreviewMaximumRequestBytes,config.PreviewMaximumResponseBytes);if err!=nil{return fmt.Errorf("initialize preview proxy: %w",err)};panelHandler:=gateway.Handler();handler:=http.HandlerFunc(func(writer http.ResponseWriter,request *http.Request){if previewProxy.MatchesHost(request.Host){previewProxy.ServeHTTP(writer,request);return};panelHandler.ServeHTTP(writer,request)});listener,err:=net.Listen("tcp",config.Listen);if err!=nil{return fmt.Errorf("listen: %w",err)};defer listener.Close();plaintext:=config.AllowPlaintextLoopback&&isLoopbackListener(listener.Addr());tlsConfig:=&tls.Config{MinVersion:tls.VersionTLS13,NextProtos:[]string{"h2","http/1.1"}};if !plaintext{certificate,loadErr:=loadTLSCertificate(config.TLSCertificate,config.TLSPrivateKey);if loadErr!=nil{return fmt.Errorf("load TLS identity: %w",loadErr)};tlsConfig.Certificates=[]tls.Certificate{certificate}};server:=&http.Server{Handler:handler,ReadHeaderTimeout:5*time.Second,ReadTimeout:35*time.Second,WriteTimeout:5*time.Minute,IdleTimeout:60*time.Second,MaxHeaderBytes:64<<10,TLSConfig:tlsConfig};ctx,cancel:=signal.NotifyContext(context.Background(),syscall.SIGINT,syscall.SIGTERM);defer cancel();serveErrors:=make(chan error,1);go func(){if plaintext{serveErrors<-server.Serve(listener);return};serveErrors<-server.ServeTLS(listener,"","")}();select{case <-ctx.Done():shutdownCtx,shutdownCancel:=context.WithTimeout(context.Background(),30*time.Second);defer shutdownCancel();_ = server.Shutdown(shutdownCtx);err=<-serveErrors;case err=<-serveErrors:};if err!=nil&&!errors.Is(err,http.ErrServerClosed){return err};return nil}

func loadConfiguration(path string)(configuration,error){var config configuration;if !filepath.IsAbs(path)||filepath.Clean(path)!=path{return config,errors.New("configuration path must be canonical and absolute")};info,err:=os.Lstat(path);if err!=nil{return config,err};if !info.Mode().IsRegular()||info.Mode()&os.ModeSymlink!=0||info.Size()<=0||info.Size()>1<<20||info.Mode().Perm()&0022!=0{return config,errors.New("unsafe configuration file")};file,err:=os.Open(path);if err!=nil{return config,err};defer file.Close();opened,err:=file.Stat();if err!=nil||!os.SameFile(info,opened){return config,errors.New("configuration file changed while opening")};decoder:=json.NewDecoder(io.LimitReader(file,(1<<20)+1));decoder.DisallowUnknownFields();if err=decoder.Decode(&config);err!=nil{return config,err};if err=decoder.Decode(&struct{}{});err!=io.EOF{return config,errors.New("trailing configuration data")};if config.Listen==""||config.CoreSocket==""||config.GatewaySigner==""||config.UIDistRoot==""||config.PreviewDomain==""||config.PreviewUpstream==""||(!config.AllowPlaintextLoopback&&(config.TLSCertificate==""||config.TLSPrivateKey=="")){return config,errors.New("incomplete gateway configuration")};return config,nil}
func isLoopbackListener(address net.Addr)bool{host,_,err:=net.SplitHostPort(address.String());if err!=nil{return false};parsed,err:=netip.ParseAddr(host);return err==nil&&parsed.IsLoopback()}
func loadTLSCertificate(certificatePath,keyPath string)(tls.Certificate,error){certificatePEM,err:=readTLSFile(certificatePath,4<<20,false);if err!=nil{return tls.Certificate{},err};privateKeyPEM,err:=readTLSFile(keyPath,1<<20,true);if err!=nil{return tls.Certificate{},err};defer func(){for index:=range privateKeyPEM{privateKeyPEM[index]=0}}();certificate,err:=tls.X509KeyPair(certificatePEM,privateKeyPEM);if err!=nil{return tls.Certificate{},err};return certificate,nil}
func readTLSFile(path string,maximum int64,secret bool)([]byte,error){if !filepath.IsAbs(path)||filepath.Clean(path)!=path{return nil,errors.New("TLS path must be canonical and absolute")};before,err:=os.Lstat(path);if err!=nil{return nil,err};if !before.Mode().IsRegular()||before.Mode()&os.ModeSymlink!=0||before.Size()<=0||before.Size()>maximum||before.Mode().Perm()&0002!=0{return nil,errors.New("unsafe TLS file")};if secret&&before.Mode().Perm()&0077!=0{return nil,errors.New("TLS private key is accessible to another account")};file,err:=os.Open(path);if err!=nil{return nil,err};defer file.Close();opened,err:=file.Stat();if err!=nil||!os.SameFile(before,opened){return nil,errors.New("TLS file changed while opening")};content,err:=io.ReadAll(io.LimitReader(file,maximum+1));if err!=nil||int64(len(content))>maximum{return nil,errors.New("TLS file exceeds configured bound")};return content,nil}
